public class CompileOrderPlannerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.Map<String, java.util.List<String>> chain = new java.util.LinkedHashMap<>();
        chain.put("Report", java.util.Arrays.asList("App"));
        chain.put("App", java.util.Arrays.asList("Util"));
        chain.put("Util", java.util.Arrays.<String>asList());
        check("dependency chain", "[Util, App, Report]",
                CompileOrderPlanner.compileOrder(chain).toString());

        java.util.Map<String, java.util.List<String>> free = new java.util.LinkedHashMap<>();
        free.put("Charlie", java.util.Arrays.<String>asList());
        free.put("Alpha", java.util.Arrays.<String>asList());
        free.put("Bravo", java.util.Arrays.<String>asList());
        check("ties broken alphabetically", "[Alpha, Bravo, Charlie]",
                CompileOrderPlanner.compileOrder(free).toString());

        java.util.Map<String, java.util.List<String>> external = new java.util.LinkedHashMap<>();
        external.put("App", java.util.Arrays.asList("java.util.List", "Util"));
        external.put("Util", java.util.Arrays.asList("java.io.File"));
        check("library dependencies ignored", "[Util, App]",
                CompileOrderPlanner.compileOrder(external).toString());

        java.util.Map<String, java.util.List<String>> cycle = new java.util.LinkedHashMap<>();
        cycle.put("Left", java.util.Arrays.asList("Right"));
        cycle.put("Right", java.util.Arrays.asList("Left"));
        check("cycle gives no order", "[]", CompileOrderPlanner.compileOrder(cycle).toString());
        check("cycle detected", true, CompileOrderPlanner.hasCycle(cycle));
        check("chain has no cycle", false, CompileOrderPlanner.hasCycle(chain));

        java.util.Map<String, java.util.List<String>> selfish = new java.util.LinkedHashMap<>();
        selfish.put("Loop", java.util.Arrays.asList("Loop"));
        check("self dependency is a cycle", true, CompileOrderPlanner.hasCycle(selfish));

        check("empty map", "[]",
                CompileOrderPlanner.compileOrder(new java.util.LinkedHashMap<String, java.util.List<String>>()).toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

