public class CompileOrderPlanner {

    public static java.util.List<String> compileOrder(java.util.Map<String, java.util.List<String>> dependencies) {
        java.util.List<String> order = new java.util.ArrayList<>();
        if (dependencies == null || dependencies.isEmpty()) {
            return order;
        }

        java.util.Map<String, java.util.Set<String>> waitingFor = new java.util.HashMap<>();
        for (String name : dependencies.keySet()) {
            java.util.Set<String> needed = new java.util.HashSet<>();
            java.util.List<String> declared = dependencies.get(name);
            if (declared != null) {
                for (String dependency : declared) {
                    if (dependencies.containsKey(dependency)) {
                        needed.add(dependency);
                    }
                }
            }
            waitingFor.put(name, needed);
        }

        java.util.TreeSet<String> ready = new java.util.TreeSet<>();
        for (String name : waitingFor.keySet()) {
            if (waitingFor.get(name).isEmpty()) {
                ready.add(name);
            }
        }

        while (!ready.isEmpty()) {
            String next = ready.pollFirst();
            order.add(next);
            for (String name : waitingFor.keySet()) {
                java.util.Set<String> needed = waitingFor.get(name);
                if (needed.remove(next) && needed.isEmpty()) {
                    ready.add(name);
                }
            }
        }

        if (order.size() != dependencies.size()) {
            return new java.util.ArrayList<>();
        }
        return order;
    }

    public static boolean hasCycle(java.util.Map<String, java.util.List<String>> dependencies) {
        if (dependencies == null || dependencies.isEmpty()) {
            return false;
        }
        return compileOrder(dependencies).isEmpty();
    }
}
